local config = {
  ui_story_30910101_1_dialog_content = "\"Tubuhnya meringkuk, terkubur di dalam tanah♫\"",
  ui_story_30910101_2_dialog_content = "Ada yang menyanyi? Lirik ini... Mungkinkah?",
  ui_story_30910101_3_dialog_content = "<color=#e8d9bb>Ini pembicaraan menakutkan saat tengah malam.</color>",
  ui_story_30910101_4_dialog_content = "Beberapa suara dapat terdengar saat tengah malam.",
  ui_story_30910101_5_dialog_content = "<color=#FFFFFF>\"Tubuhnya meringkuk, terkubur di dalam tanah♫\"</color>",
  ui_story_30910101_6_dialog_content = "Melodinya berulang lagi dan lagi",
  ui_story_30910101_7_dialog_content = "<color=#FFFFFF>\"Antusias sekaligus ngeri untuk tumbuh dewasa♪\"</color>",
  ui_story_30910101_8_dialog_content = "Musiknya tiba-tiba berhenti.",
  ui_story_30910101_9_dialog_content = "<color=#FFFFFF>\"Kubisikkan padanya tentang...♫\"</color>",
  ui_story_30910101_10_dialog_content = "<color=#FFFFFF>\"Huu-huu...\"</color>",
  ui_story_30910101_11_dialog_content = "Isakan sedih terus berulang.",
  ui_story_30910101_12_dialog_content = "Hantu berdesah, mengganggu tidur yang damai♪",
  ui_story_30910101_13_dialog_content = "<color=#FFFFFF>\"Kubisikkan padanya tentang...♫\"</color>",
  ui_story_30910101_14_dialog_content = "<color=#FFFFFF>\"Tentang...♫\"</color>",
  ui_story_30910101_15_dialog_content = "Ini adalah kisah teror Colossus.",
  ui_story_30910101_16_dialog_content = "Semua orang dewasa muak dengan teror♪",
  ui_story_30910101_17_dialog_content = "*Dengarkan nyanyian lagu ini*",
  ui_story_30910101_18_dialog_content = "Lirik dan melodi ini... Sama persis dengan cerita teror Keating!",
  ui_story_30910101_19_dialog_content = "\"Antusias sekaligus ngeri untuk tumbuh dewasa♪\"",
  ui_story_30910101_20_dialog_content = "\"Kubisikkan padanya tentang...\"",
  ui_story_30910101_21_dialog_content = "(Jadi, ini suara Chloe.)",
  ui_story_30910101_22_dialog_content = "\"Kubisikkan padanya tentang...\"",
  ui_story_30910101_23_dialog_content = "\"Tentang...\"",
  ui_story_30910101_24_dialog_content = "*Meneteskan air mata*",
  ui_story_30910101_25_dialog_content = "(Mengapa... mengapa dia menangis? Aku harus...)",
  ui_story_30910101_26_option_content = "Hibur dia",
  ui_story_30910101_27_dialog_content = "Chloe, kamu baik-baik saja?",
  ui_story_30910101_28_dialog_content = "Oh, kamu rupanya, PlayerName. Senang kamu bertanya.",
  ui_story_30910101_29_dialog_content = "Air matamu berlinang...",
  ui_story_30910101_30_dialog_content = "Jangan khawatir. Aku... Air mata adalah air hujan yang menyuburkan kuncup menjadi bunga...",
  ui_story_30910101_31_dialog_content = "Aku hanya sedikit kehilangan kendali atas diriku.",
  ui_story_30910101_32_option_content = "Jangan ganggu dia",
  ui_story_30910101_33_dialog_content = "\"Kubisikkan padanya tentang...\"",
  ui_story_30910101_34_dialog_content = "Baiklah... Ia tahu aku masih tidak bisa...",
  ui_story_30910101_35_dialog_content = "*Menatap Chloe dengan rasa prihatin*",
  ui_story_30910101_36_dialog_content = "Oh, kamu rupanya, PlayerName? Maaf kamu melihatku dalam kondisi begini.",
  ui_story_30910101_37_dialog_content = "Maaf... Aku selalu mulai terisak tanpa sadar...",
  ui_story_30910101_38_dialog_content = "Saat dawainya dipetik, emosiku meluap.",
  ui_story_30910101_39_dialog_content = "Nyanyian dapat terdengar dari Colossus. Lagu merdu itu berulang lagi dan lagi, tetapi selalu berakhir tiba-tiba pada nada yang sama...",
  ui_story_30910101_40_dialog_content = "Jadi, kamu adalah tokoh utama dalam kisah teror Keating.",
  ui_story_30910101_41_dialog_content = "Aku merasa sangat bersalah karena dilihat oleh anak-anak itu.",
  ui_story_30910101_42_dialog_content = "Jelas aku yang lebih tua, tetapi aku gagal menjadi panutan.",
  ui_story_30910101_43_dialog_content = "Apakah lagu itu yang membuatmu menangis?",
  ui_story_30910101_44_dialog_content = "Kedengarannya seperti lagu yang mengharukan.",
  ui_story_30910101_45_dialog_content = "Benar. Bahkan liriknya sama bersemangatnya seperti matahari. Namun, aku... sepertinya tidak bisa selesai menyanyikannya.",
  ui_story_30910101_46_dialog_content = "\"Kubisikkan padanya tentang betapa indahnya hidup.\"",
  ui_story_30910101_X47_dialog_content = "Mereka begitu polos dan penuh harapan.",
  ui_story_30910101_47_dialog_content = "Ini lagu yang baru saja kupelajari. Judulnya <color=#FFB400>—White Flower—</color>.",
  ui_story_30910101_48_dialog_content = "<color=#FFB400>—White Flower?—</color>",
  ui_story_30910101_49_dialog_content = "Ya.",
  ui_story_30910101_50_dialog_content = "Tokoh utama dalam lagu ini menanam benih bunga putih dan menunggunya berakar dan bertunas.",
  ui_story_30910101_51_dialog_content = "Dia memberi tahu benih yang terkubur di dalam tanah tentang semua hal baik di dunia, seperti air hujan, angin yang hangat, dan sinar matahari.",
  ui_story_30910101_52_dialog_content = "Dia bilang pada benih itu agar tumbuh cepat sehingga bisa mulai menikmati hidup.",
  ui_story_30910101_53_dialog_content = "Kedengarannya begitu mengharukan. Sang penulis pastilah seseorang yang sangat menikmati hidup.",
  ui_story_30910101_54_dialog_content = "Dia... gadis yang rapuh. Dia muridku.",
  ui_story_30910101_55_dialog_content = "Muridmu?",
  ui_story_30910101_56_dialog_content = "Ya. Kamu tahu, aku ini pemusik.",
  ui_story_30910101_57_dialog_content = "Musik adalah puisi yang mengalir. Murid-muridku menyukai musik sama sepertiku.",
  ui_story_30910101_58_dialog_content = "Kami berbicara lewat lagu dan jiwa kami berpadu dalam melodi.",
  ui_story_30910101_59_dialog_content = "Itu sebabnya aku sangat mengenal dia. Aku mengerti betapa bersemangatnya dia, dan kamu bisa merasakannya dalam lagu-lagunya.",
  ui_story_30910101_60_dialog_content = "Aku bisa merasakannya.",
  ui_story_30910101_61_dialog_content = "Dia bangun pagi-pagi, merapikan tempat tidur dan kamarnya.",
  ui_story_30910101_62_dialog_content = "Dia menanam banyak bunga cantik di balkon dan menyapanya lewat puisi sembari menyiraminya.",
  ui_story_30910101_63_dialog_content = "Dia juga memanggang kue pastri, membungkusnya sebagai hadiah, dan memberikannya kepada orang yang lewat.",
  ui_story_30910101_64_dialog_content = "Dia pernah bilang bahwa jika dia berhasil membuat lagu yang sempurna, dia ingin aku memainkannya.",
  ui_story_30910101_65_option_content = "Aku ingin menjadi temannya.",
  ui_story_30910101_66_dialog_content = "Kamu ingin mencicipi kue pastrinya, 'kan, PlayerName?",
  ui_story_30910101_67_dialog_content = "Begitulah faktanya!",
  ui_story_30910101_68_dialog_content = "(Namun, bagaimana bisa lagu semengharukan ini membuat Chloe begitu sedih sehingga dia tidak bisa terus bernyanyi?)",
  ui_story_30910101_69_option_content = "Aku juga merapikan Colossus setiap hari.",
  ui_story_30910101_70_dialog_content = "Tentu, dengan Firefly.",
  ui_story_30910101_71_dialog_content = "Jangan merasa malu karenanya, PlayerName. Semangat kita dalam hidup adalah hal yang membuat kita bersinar terang.",
  ui_story_30910101_72_dialog_content = "(Namun, bagaimana bisa lagu semengharukan ini membuat Chloe begitu sedih sehingga dia tidak bisa terus bernyanyi?)",
  ui_story_30910101_73_dialog_content = "Kalau dipikir, apakah ini jenis bunga putih yang dimaksud dalam lagu itu?",
  ui_story_30910101_74_dialog_content = "<color=#FFB400>Jenis bunga yang dipupuk dengan Lumina dan ditenun dengan sihir.</color>",
  ui_story_30910101_75_dialog_content = "Kelopak bunga putih mencium telapak tangan, seolah-olah mengucapkan salam perpisahan.",
  ui_story_30910101_76_dialog_content = "PlayerName... Kamu mengerti arti dari bunga-bunga ini?",
  ui_story_30910101_77_option_content = "Aku pernah lihat Keating menggunakannya untuk menjahili orang.",
  ui_story_30910101_X77_dialog_content = "Maksudmu, saat mereka meletakkan bunga di belakang telinga City Lord?",
  ui_story_30910101_78_dialog_content = "Namanya juga anak-anak. Masih tidak peduli dengan dunia. Maafkan mereka.",
  ui_story_30910101_79_option_content = "Uriah tampaknya punya banyak bunga ini.",
  ui_story_30910101_80_dialog_content = "Arah kelopak putih terjatuh adalah alam mimpi orang yang tertidur.",
  ui_story_30910101_81_dialog_content = "Bunga-bunga putih memungkinkan mereka yang tiada untuk beristirahat dan menghibur yang hidup. Bunga ini adalah kebaikan Uriah.",
  ui_story_30910101_82_dialog_content = "Bunga ini melambangkan \"<color=#FFB400>perpisahan yang tragis</color>\".",
  ui_story_30910101_83_dialog_content = "Apa maksudmu...",
  ui_story_30910101_84_dialog_content = "Persis... seperti yang kamu pikirkan.",
  ui_story_30910101_85_dialog_content = "Dia menulis lagu yang dipenuhi harapan untuk hidup ketika sakit, tetapi akhirnya dia harus menyerah melawan penyakit itu.",
  ui_story_30910101_X85_dialog_content = "Ini adalah bayangan di balik sinar matahari. Lirik penuh harapan yang dihantui mimpi buruk yang tiada henti menyiksaku.",
  ui_story_30910101_86_dialog_content = "Aku seperti anak naif, tidak bisa keluar dari bayangan...",
  ui_story_30910101_87_dialog_content = "Aku tahu aku masih tidak bisa memainkan lagu ini. Tidak bisa...",
  ui_story_30910101_88_option_content = "*Berikan tisu kepada Chloe*",
  ui_story_30910101_89_dialog_content = "Ini untuk mengeringkan air mataku, PlayerName?",
  ui_story_30910101_90_option_content = "*Mulai Bersenandung*",
  ui_story_30910101_91_dialog_content = "\"Bagaimana harus kurawat bunga putih mungil ini ♪ Akan kunanti sampai akar dan tunasnya muncul ♩ Bagaimana dahan dan daunnya akan tumbuh ♫\"",
  ui_story_30910101_92_dialog_content = "Kamu... Kamu bernyanyi, PlayerName?",
  ui_story_30910101_93_dialog_content = "Setelah mendengarkan nyanyianmu, aku benar-benar ingin mengenal si penulisnya.",
  ui_story_30910101_95_dialog_content = "PlayerName...",
  ui_story_30910101_96_dialog_content = "Dia pasti menulis lagu ini dengan harapan lebih banyak orang yang mendengarnya.",
  ui_story_30910101_97_dialog_content = "(PlayerName tampak serius.)",
  ui_story_30910101_98_dialog_content = "Kamu berharap aku akan selesai memainkannya, PlayerName?",
  ui_story_30910101_99_dialog_content = "...",
  ui_story_30910101_100_dialog_content = "Kamu benar. Dia memercayaiku dengan apa yang ingin dia katakan, tetapi di sinilah aku, terombang-ambing dalam kesedihan, tidak dapat meneruskan pesannya.",
  ui_story_30910101_101_dialog_content = "Jika aku seperti ini, hatinya pasti akan hancur.",
  ui_story_30910101_102_dialog_content = "Sayap-sayap lagu ini akan mengingatkan orang betapa mereka merindukan yang telah tiada. Dengarkanlah lagu harapan ini.",
  ui_story_30910101_103_dialog_content = "\"Bunga Putih.\"",
  ui_story_30910101_104_dialog_content = "\"Bagaimana harus kurawat bunga putih mungil ini\"? ♪",
  ui_story_30910101_A1_dialog_content = "\"Akan kunanti sampai akar dan tunasnya muncul, dan melihat dahan dan daunnya tumbuh.\" ♪",
  ui_story_30910101_105_dialog_content = "\"Kubisikkan padanya tentang betapa indahnya hidup.\" ♪",
  ui_story_30910101_106_dialog_content = "\"Hujan adalah air mata yang menetes untuk tanah, memberinya masa muda yang abadi\"",
  ui_story_30910101_107_dialog_content = "\"Angin adalah senandung hutan, menyanyikan keindahan pemandangan\"",
  ui_story_30910101_108_dialog_content = "\"Cahaya adalah tatapan langit, begitu tulus dan lembut\"",
  ui_story_30910101_109_dialog_content = "\"Tumbuhlah, tumbuh\"",
  ui_story_30910101_110_dialog_content = "\"Andai aku masih punya waktu♪\"",
  ui_story_30910101_111_dialog_content = "\"Andai aku masih punya waktu♪\"",
  ui_story_30910601_1_dialog_content = "Apakah ini tempat gladi resik pernikahan akan diadakan?",
  ui_story_30910601_2_dialog_content = "Anda sangat baik, datang ke latihan dan segalanya! Sungguh, aku terharu...",
  ui_story_30910601_3_dialog_content = "Ah, ayolah! Kenapa kau menangis lagi?",
  ui_story_30910601_4_dialog_content = "Saya diundang ke pernikahan hari ini, jadi saya memutuskan untuk datang lebih awal karena saya bebas.",
  ui_story_30910601_5_dialog_content = "\"Siapa bilang orang Caelest tidak tunduk?\"",
  ui_story_30910601_6_dialog_content = "\"Betapa tunduknya dia, saat melihat air mata seorang gadis!\" ♫",
  ui_story_30910601_7_dialog_content = "\"Bibir mengepak, wajah memerah.\"",
  ui_story_30910601_8_dialog_content = "\"Terlihat lucu seperti siput.\" ♪",
  ui_story_30910601_9_dialog_content = "Baiklah, cukup dengan godaannya.",
  ui_story_30910601_10_dialog_content = "Jangan mengolok-olok Caelestite! Dia adalah orang yang paling manis dan lembut.",
  ui_story_30910601_11_dialog_content = "Ha, aku tidak seperti itu, Chloe. ... Sebenarnya, ahem, mungkin memang begitu.",
  ui_story_30910601_12_dialog_content = "\"Jangan menganggap serius semua pujian\" ♪",
  ui_story_30910601_13_dialog_content = "\"Itu aturan emas yang tidak pernah—\"",
  ui_story_30910601_14_dialog_content = "Berhenti! Sudah cukup!",
  ui_story_30910601_15_dialog_content = "Saya tidak mengerti mengapa Anda diundang ke pesta pernikahan. Tolong jangan bilang kau berencana mengejek pengantin baru.",
  ui_story_30910601_16_dialog_content = "Kedua sejoli itu jungkir balik.",
  ui_story_30910601_17_dialog_content = "Jatuh cinta memang menurunkan kecerdasan seseorang.",
  ui_story_30910601_18_dialog_content = "Bukan hanya kecerdasanmu! Rasa juga keluar jendela.",
  ui_story_30910601_19_dialog_content = "Tempat pernikahan ini terlihat seperti seseorang memuntahkan warna merah jambu.",
  ui_story_30910601_20_dialog_content = "Sangat buruk!",
  ui_story_30910601_21_dialog_content = "Diam, tolong! Pasangan bahagia dan keluarga mereka akan datang!",
  ui_story_30910601_22_dialog_content = "Jadi ini pasti Chloe, musisi terkenal itu? Cukup menakjubkan!",
  ui_story_30910601_23_dialog_content = "Tidak ada yang bisa dibandingkan denganmu, sayangku.",
  ui_story_30910601_24_dialog_content = "Oh kamu! Jangan mengatakan hal-hal itu di depan karakter yang begitu terhormat!",
  ui_story_30910601_25_dialog_content = "PlayerName, Aku akan meninggalkanmu di sini. Aku harus pergi berlatih.",
  ui_story_30910601_26_dialog_content = "Saya merasa terhormat bisa mendengar Anda tampil.",
  ui_story_30910601_27_dialog_content = "Wow! Ini dimulai! Menarik sekali!",
  ui_story_30910601_28_dialog_content = "\"Momen terindah di dunia...\" ♫",
  ui_story_30910601_29_dialog_content = "\"Adalah ketika kamu pertama kali muncul di hadapanku\" ♪",
  ui_story_30910601_30_dialog_content = "\"Dalam hidup yang begitu tanpa harapan, begitu penuh dengan kesengsaraan,\"",
  ui_story_30910601_31_dialog_content = "\"Kamu selalu jiwa yang lembut dan menghangatkan.\" ♪",
  ui_story_30910601_32_dialog_content = "\"Cinta kita akan selamat dari semua badai,\"",
  ui_story_30910601_33_dialog_content = "\"Oh, cinta kita akan bertahan sampai kita berada di kuburan kita ...\"",
  ui_story_30910601_34_dialog_content = "\"Dan di atas, kita akan bersama lagi.\"",
  ui_story_30910601_35_dialog_content = "(Er... lagu ini terdengar agak menyedihkan untuk acara ini.)",
  ui_story_30910601_36_dialog_content = "(Meskipun berbicara tentang cinta abadi, sepertinya tidak cocok untuk pernikahan.)",
  ui_story_30910601_37_dialog_content = "(Kemudian lagi, mungkin saya terlalu banyak berpikir. Pengantin mungkin menyukainya.)",
  ui_story_30910601_38_dialog_content = "*Hiks* Uwaaah! Ini sangat menyedihkan! Saya tidak memiliki cinta abadi semacam itu!",
  ui_story_30910601_39_dialog_content = "Sayang! Kemana kamu pergi?",
  ui_story_30910601_40_dialog_content = "Pengantin wanita kabur?! Apa yang sedang terjadi?!",
  ui_story_30910601_41_dialog_content = "Ya ampun... Itu tak terduga...",
  ui_story_30910601_42_dialog_content = "Chloe! Apakah kamu baik-baik saja?",
  ui_story_30910601_43_dialog_content = "Aku pasti telah melakukan sesuatu yang salah... Aku baru saja merusak pernikahan...",
  ui_story_30910601_44_dialog_content = "Jangan menyalahkan diri sendiri! Turun dulu. Pelan-pelan... aku punya kamu.",
  ui_story_30910601_45_dialog_content = "\"Pengantin wanita pergi dengan tergesa-gesa!\"",
  ui_story_30910601_46_dialog_content = "\"Pengantin pria mengejar!\"",
  ui_story_30910601_47_dialog_content = "\"Keluarga itu semua berwajah muram!\"",
  ui_story_30910601_48_dialog_content = "\"Tempat itu akan sia-sia!\"",
  ui_story_30910601_49_dialog_content = "Apa yang sebenarnya terjadi? Mengapa pengantin wanita kabur begitu saja?",
  ui_story_30910601_50_dialog_content = "Apa laguku seburuk itu?",
  ui_story_30910601_51_dialog_content = "APA?! Pengantin wanita membatalkan pernikahan? Itu tidak bisa diterima!",
  ui_story_30910601_52_dialog_content = "Semua undangan telah diterima, dan para tamu akan tiba hanya dalam beberapa jam!",
  ui_story_30910601_53_dialog_content = "Batalkan! Batalkan saja. Kami tidak bisa memaksa putri kami untuk menikah. Hubungi para tamu, beri tahu mereka bahwa ini tidak terjadi!",
  ui_story_30910601_54_dialog_content = "!!!",
  ui_story_30910601_55_dialog_content = "Mereka membatalkan pernikahan? Seperti itu?",
  ui_story_30910601_56_dialog_content = "Orang tua yang sembrono membesarkan anak-anak yang impulsif.",
  ui_story_30910601_57_dialog_content = "Cinta pada pandangan pertama seringkali hanya sedalam kulit.",
  ui_story_30910601_58_dialog_content = "Tanpa berpikir untuk menikah besok!",
  ui_story_30910601_59_dialog_content = "Tapi sudah terlambat untuk menyesali hari setelahnya.",
  ui_story_30910601_60_dialog_content = "Apakah itu yang terjadi? Mereka memutuskan untuk menikah karena iseng?",
  ui_story_30910601_61_dialog_content = "Lagu Chloe pasti membuat pengantin wanita yang emosional mulai meragukan keputusannya lagi.",
  ui_story_30910601_62_dialog_content = "Dan kemudian dia mogok dan lari.",
  ui_story_30910601_63_dialog_content = "Sungguh menakjubkan seberapa cepat Anda dapat menganalisis situasi, PlayerName.",
  ui_story_30910601_64_dialog_content = "Bagian mana dari itu yang tidak jelas?",
  ui_story_30910601_65_dialog_content = "Dia mendengarnya dari anggota keluarga sendiri.",
  ui_story_30910601_66_dialog_content = "Ehem, baiklah. Itu kurang lebih begitu.",
  ui_story_30910601_67_dialog_content = "Jujurlah padaku, PlayerName. Apakah lagu saya benar-benar buruk?",
  ui_story_30910601_68_dialog_content = "Tidak, tidak sama sekali! Mungkin saja itu bukan yang paling cocok untuk pernikahan ...",
  ui_story_30910601_69_dialog_content = "Benarkah…?",
  ui_story_30910601_70_dialog_content = "Yang saya inginkan hanyalah agar pernikahan ini sempurna, dan sekarang semuanya hancur!",
  ui_story_30910601_71_dialog_content = "Mungkin karena saya tidak terlalu mengerti cinta, jadi saya hanya bisa membuat lagu berdasarkan imajinasi saya sendiri.",
  ui_story_30910601_72_dialog_content = "Tapi lagu itu mengungkapkan apa yang menurut saya bentuk cinta yang paling sejati adalah—",
  ui_story_30910601_73_dialog_content = "Bahwa di dunia yang kejam dan kejam ini, ada keindahan dalam dua orang yang mengorbankan diri demi cinta.",
  ui_story_30910601_74_dialog_content = "Tapi tidak ada jumlah air mata yang bisa menebus apa yang telah saya lakukan ...",
  ui_story_30910601_75_dialog_content = "Jangan menangis, ayolah. Ini bukan salahmu.",
  ui_story_30910601_76_dialog_content = "\"Jangan salahkan dirimu, cengeng. Kamu bernyanyi tentang cinta yang ideal.\"",
  ui_story_30910601_77_dialog_content = "\"Tapi pernikahan adalah kontrak, pertukaran nilai!\" ♫",
  ui_story_30910601_78_dialog_content = "\"Ini kontrak aliansi untuk orang jahat\" ♪",
  ui_story_30910601_79_dialog_content = "\"Digunakan terutama untuk menindas gadis-gadis miskin.\"",
  ui_story_30910601_80_dialog_content = "\"Hanya orang bodoh yang jatuh cinta, dan hanya orang bodoh yang menikah.\"",
  ui_story_30910601_81_dialog_content = "Benarkah begitu cara kalian memandang cinta?",
  ui_story_30910601_82_dialog_content = "Apa pandanganmu tentang cinta, PlayerName?",
  ui_story_30910601_83_option_content = "Romantis dan indah",
  ui_story_30910601_84_dialog_content = "Saya telah melakukan perjalanan jauh, mengalami banyak hal, dan bertemu dengan berbagai macam orang.",
  ui_story_30910601_85_dialog_content = "Beberapa orang menjadi gila karena cinta, sementara yang lain melihatnya sebagai alat. Tapi ada juga yang diselamatkan oleh cinta.",
  ui_story_30910601_86_dialog_content = "Saya pikir pasti ada sisi yang murni dan bahagia untuk mencintai.",
  ui_story_30910601_87_option_content = "Sulit untuk diungkapkan...",
  ui_story_30910601_88_dialog_content = "Saya telah melakukan perjalanan jauh, mengalami banyak hal, dan bertemu dengan berbagai macam orang.",
  ui_story_30910601_89_dialog_content = "Beberapa orang menjadi gila karena cinta, sementara yang lain melihatnya sebagai alat. Tapi ada juga yang diselamatkan oleh cinta.",
  ui_story_30910601_90_dialog_content = "Menurutku cinta itu multidimensi.",
  ui_story_30910601_91_dialog_content = "Anda telah menginspirasi saya.",
  ui_story_30910601_92_dialog_content = "Sepertinya setiap orang memiliki definisi cinta yang berbeda.",
  ui_story_30910601_93_dialog_content = "Mungkin tidak ada definisi yang cocok untuk semua, tidak ada jawaban yang benar.",
  ui_story_30910601_94_dialog_content = "Mungkin lagu saya kurang lengkap...",
  ui_story_30910601_95_dialog_content = "Dia kembali! Pengantin wanita kembali!",
  ui_story_30910601_96_dialog_content = "Lanjutkan dengan latihan!",
  ui_story_30910601_97_dialog_content = "Langsung aja ke bagian pentingnya!",
  ui_story_30910601_98_dialog_content = "Bisakah kedua mempelai bertukar sumpah?",
  ui_story_30910601_99_dialog_content = "Oh! Jantung hatiku! Anda adalah satu-satunya cahaya dalam hidup saya!",
  ui_story_30910601_100_dialog_content = "Anda adalah penjelmaan puisi, embun pagi menjadi daging. Bahkan gemuruh amarahmu lebih indah dari musik apapun!",
  ui_story_30910601_101_dialog_content = "Dan sekarang, giliran mempelai wanita.",
  ui_story_30910601_102_dialog_content = "...",
  ui_story_30910601_103_dialog_content = "Pengantin?",
  ui_story_30910601_104_dialog_content = "Oh, ini semua sangat palsu.",
  ui_story_30910601_105_dialog_content = "Oh, api cinta! Hancurkan aku! Apa yang dapat saya lakukan untuk membuktikan bahwa cinta saya benar?",
  ui_story_30910601_106_dialog_content = "Aduh, saya tidak berpikir kata-katanya mencapai dia. Ini canggung.",
  ui_story_30910601_107_dialog_content = "Hm? Kemana kamu pergi, Chloe?",
  ui_story_30910601_108_dialog_content = "Saya bertanggung jawab atas kekacauan ini, jadi saya harus membereskannya.",
  ui_story_30910601_109_dialog_content = "Ini benar-benar tidak ada hubungannya dengan dia.",
  ui_story_30910601_110_dialog_content = "Namun dia bersikeras mengambil tanggung jawab.",
  ui_story_30910601_111_dialog_content = "Aaa dan dia naik ke atas panggung.",
  ui_story_30910601_112_dialog_content = "Ulangan dimulai.",
  ui_story_30910601_113_dialog_content = "\"Cinta bisa begitu kuat namun juga sangat rapuh\" ♫",
  ui_story_30910601_114_dialog_content = "\"Secerah kaca patri dan rapuh ...\"",
  ui_story_30910601_115_dialog_content = "\"Cinta itu lembut tapi berduri seperti duri\" ♪",
  ui_story_30910601_116_dialog_content = "\"Terlalu kuat atau terlalu lemah, hasilnya tidak akan sempurna\" ♪",
  ui_story_30910601_117_dialog_content = "\"Peliharalah cinta dengan benar...\" ♪",
  ui_story_30910601_118_dialog_content = "\"Dan saksikan itu mekar, dengan sendirinya.\" ♪",
  ui_story_30910601_119_dialog_content = "\"Gelombang yang menggelora adalah cinta, namun demikian juga air yang tenang dan tenang.\"",
  ui_story_30910601_120_dialog_content = "\"Berapapun usia seseorang, cintai seolah-olah ini pertama kalinya\" ♫",
  ui_story_30910601_121_dialog_content = "Lagu yang sangat indah! Sangat mirip cinta!",
  ui_story_30910601_122_dialog_content = "*Menangis*... Dan sangat mirip dengan cintaku padamu...",
  ui_story_30910601_123_dialog_content = "Apakah Anda ingat, pada kencan terakhir kami, Anda bertanya kepada saya tentang nama bunga dan saya tidak tahu jawabannya?",
  ui_story_30910601_124_dialog_content = "Nah, ketika saya sampai di rumah, saya mempelajari semua nama bunga! Bahkan jika Anda tidak pernah bertanya kepada saya lagi.",
  ui_story_30910601_125_dialog_content = "Saya tidak bertanya lagi karena saya berasumsi Anda tidak akan tahu, dan saya tidak ingin orang lain tahu bahwa Anda bodoh-bodoh yang tidak bisa membedakan mawar!",
  ui_story_30910601_126_dialog_content = "Astaga! Aku tidak percaya cintaku padamu telah mencapai titik ini.",
  ui_story_30910601_127_dialog_content = "Apa?! Jika mawar yang kau inginkan, aku tahu rosa chinensis, rosa canina...",
  ui_story_30910601_128_dialog_content = "Heehee... Kau benar-benar billy yang konyol!",
  ui_story_30910601_129_dialog_content = "Jadi apakah pasangan bahagia itu baik-baik saja sekarang?",
  ui_story_30910601_130_dialog_content = "Tolong biarkan sumpah dibaca.",
  ui_story_30910601_131_dialog_content = "Saya berhutang maaf kepada semua orang, terutama tunangan saya yang tersayang!",
  ui_story_30910601_132_dialog_content = "Ketika saya pertama kali mendengar lagu itu, saya terus berpikir bahwa ini tidak mungkin cinta sejati jika belum diuji.",
  ui_story_30910601_133_dialog_content = "Tapi saya cukup beruntung memiliki pendidikan yang riang, dengan pengalaman saya yang paling menyakitkan menjadi potongan kertas yang buruk.",
  ui_story_30910601_134_dialog_content = "Sesuatu yang dilakukan sendiri secara tidak sengaja, yang bahkan tidak terlalu menyakitkan jika saya tidak memikirkannya.",
  ui_story_30910601_135_dialog_content = "Oof, itu sangat menyakitkan!",
  ui_story_30910601_136_dialog_content = "Itu sedikit menyakitkan, tetapi bahkan tidak sebanding dengan rasa sakit yang datang dengan cinta yang bernasib sial.",
  ui_story_30910601_137_dialog_content = "Dan itulah mengapa saya goyah, betapapun singkatnya, dalam hal cinta dan pernikahan.",
  ui_story_30910601_138_dialog_content = "Tapi aku menyadari sekarang bahwa, meskipun cintaku tidak pernah melibatkan penderitaan atau rintangan, dan itu tidak pernah benar-benar diuji...",
  ui_story_30910601_139_dialog_content = "Itu tetap cinta, tidak peduli seberapa biasa.",
  ui_story_30910601_140_dialog_content = "Cinta dalam bentuk apa pun tampaknya jauh dari biasa ...",
  ui_story_30910601_141_dialog_content = "Apakah Anda berdua yakin pernikahan itu kembali?",
  ui_story_30910601_142_dialog_content = "Ya!",
  ui_story_30910601_143_dialog_content = "Buru-buru! Kami harus memberi tahu para tamu bahwa pernikahan akan berjalan sesuai rencana!",
  ui_story_30910601_144_dialog_content = "Oh tidak! Saya baru saja memberi tahu mereka semua bahwa itu dibatalkan! Dan sekarang saya harus memberi tahu semua orang lagi?!",
  ui_story_30910601_145_dialog_content = "Oh, penghinaan! Kami akan menjadi bahan tertawaan para bangsawan!",
  ui_story_30910601_146_dialog_content = "Diam! Keluarga lain telah melakukan hal-hal bodoh mereka, tidak ada yang akan peduli dengan cegukan kecil kita.",
  ui_story_30910601_147_dialog_content = "Terlepas dari itu, setidaknya semuanya baik-baik saja yang berakhir dengan baik.",
  ui_story_30910601_148_dialog_content = "Semoga mereka selalu bebas dan bahagia seperti hari ini!",
  ui_story_30910601_149_dialog_content = "Terima kasih banyak untukmu, Chloe. Pertunjukan yang sangat indah, sungguh mengharukan!",
  ui_story_30910601_150_dialog_content = "Kamu benar-benar terlalu baik.",
  ui_story_30910601_151_dialog_content = "\"Cinta hanyalah mimpi yang cepat berlalu.\"",
  ui_story_30910601_152_dialog_content = "\"Atau kadang-kadang mimpi buruk!\"",
  ui_story_30910601_153_dialog_content = "\"Cobalah untuk memegangnya, dan itu terlepas.\"",
  ui_story_30910601_154_dialog_content = "\"Cobalah untuk bangun, dan itu menghancurkanmu.\"",
  ui_story_30910601_155_dialog_content = "Kenapa kalian bertingkah lagi?",
  ui_story_30910601_156_dialog_content = "Kami hanya menyanyikan kebenaran.",
  ui_story_30910601_157_dialog_content = "Saya khawatir pasangan ini mungkin berada di jalan yang berbatu.",
  ui_story_30910601_158_dialog_content = "Akan ada banyak drama dalam hidup mereka.",
  ui_story_30910601_159_dialog_content = "Oooh, bagus. Saya suka drama yang bagus.",
  ui_story_30910601_160_dialog_content = "Meski begitu, butuh banyak usaha untuk membuat mereka berdamai, jadi bagaimana kalau membiarkan mereka sendirian?",
  ui_story_30910601_161_dialog_content = "Baiklah kalau begitu. Kami akan mengganggu Anda sebagai gantinya!",
  ui_story_30910601_162_dialog_content = "Tapi apa hubungannya cinta denganmu?",
  ui_story_30910601_163_dialog_content = "Cinta bukanlah masalah yang membuat Anda terjaga di malam hari.",
  ui_story_30910601_164_dialog_content = "Ini rambut rontok.",
  ui_story_30910601_165_dialog_content = "Saya tahu Anda tidak mampu mengatakan sesuatu yang baik tentang saya!",
  ui_story_30910601_166_dialog_content = "Hidup membutuhkan pertarakan jangka panjang; cinta hanya perlu menjadi kenyataan.",
  ui_story_30910601_167_dialog_content = "Jadilah tulus, baik hati. Bahkan ketika diganggu oleh kekhawatiran kecil.",
  ui_story_30910601_168_dialog_content = "Karunia kehidupan tidak sering diberikan kepada kita dengan sendok perak.",
  ui_story_30910601_169_dialog_content = "Saya setuju dengan Chloe. Selama cinta mereka benar, mereka akan menemukan kebahagiaan.",
  ui_story_30910601_170_dialog_content = "\"Dan begitulah tirai itu jatuh.\"",
  ui_story_30910601_171_dialog_content = "\"La-la-la-la!\"",
  ui_story_30910601_172_dialog_content = "\"Semanis apa pun cinta itu,\"",
  ui_story_30910601_173_dialog_content = "\"pernikahan hanyalah penderitaan!\"",
  ui_story_30910601_174_dialog_content = "<size=45>Hentikan, sudah!</size>"
}
return config
